def solve(clauses):
    variables = sorted({abs(lit) for clause in clauses for lit in clause})

    def simplify(clauses, lit):
        out = []
        for clause in clauses:
            if lit in clause:
                continue
            out.append([other for other in clause if other != -lit])
        return out

    def dpll(clauses, model):
        while True:
            unit = None
            for clause in clauses:
                if not clause:
                    return None
                if len(clause) == 1:
                    unit = clause[0]
                    break
            if unit is None:
                break
            if model.get(abs(unit), unit > 0) != (unit > 0):
                return None
            model[abs(unit)] = unit > 0
            clauses = simplify(clauses, unit)
        if not clauses:
            return model
        lit = clauses[0][0]
        for guess in (lit, -lit):
            branch = dict(model)
            branch[abs(guess)] = guess > 0
            found = dpll(simplify(clauses, guess), branch)
            if found is not None:
                return found
        return None

    found = dpll([list(clause) for clause in clauses], {})
    if found is None:
        return None
    return {var: found.get(var, False) for var in variables}
